Q = [
# P03 (complemento) — critérios do art. 2º, parágrafo único
("P03",["2.VIII"],"C","conceito_correto",2,"Nos processos administrativos, devem ser observadas as formalidades essenciais à garantia dos direitos dos administrados, e não toda e qualquer formalidade.","Art. 2º, parágrafo único, VIII.","","p03i",{}),
("P03",["2.IX"],"E","troca_efeito",2,"Nos processos administrativos, devem ser adotadas formas rigorosas e detalhadas, a fim de propiciar o máximo grau de certeza e segurança, ainda que em prejuízo da celeridade.","Art. 2º, parágrafo único, IX: formas simples, suficientes para propiciar adequado grau de certeza, segurança e respeito aos direitos dos administrados.","exige formas rigorosas","p03i",{}),
("P03",["2.IV"],"C","conceito_correto",1,"Exige-se, nos processos administrativos, atuação segundo padrões éticos de probidade, decoro e boa-fé.","Art. 2º, parágrafo único, IV.","","p03j",{}),
("P03",["2.VII"],"C","conceito_correto",2,"Nos processos administrativos, deve haver indicação dos pressupostos de fato e de direito que determinarem a decisão.","Art. 2º, parágrafo único, VII.","","p03k",{}),
# P16 — Recurso: cabimento, instâncias, legitimidade (arts. 56 a 58)
("P16",["56"],"C","conceito_correto",1,"Das decisões administrativas cabe recurso, em face de razões de legalidade e de mérito.","Art. 56, caput.","","p16a",{}),
("P16",["56"],"E","restricao_indevida",1,"Das decisões administrativas cabe recurso apenas por razões de legalidade, pois o mérito do ato é insindicável na via administrativa.","Art. 56, caput: cabe recurso por razões de legalidade e de mérito.","exclui o mérito","p16a",{}),
("P16",["56"],"C","conceito_correto",2,"O recurso administrativo é dirigido à autoridade que proferiu a decisão, a qual, se não a reconsiderar no prazo de cinco dias, o encaminhará à autoridade superior.","Art. 56, § 1º.","","p16b",{}),
("P16",["56"],"E","troca_autoridade",2,"O recurso administrativo é dirigido diretamente à autoridade superior à que proferiu a decisão, sem possibilidade de reconsideração pela autoridade recorrida.","Art. 56, § 1º: dirige-se à autoridade que proferiu a decisão, que pode reconsiderá-la em cinco dias.","dispensa a reconsideração","p16b",{}),
("P16",["56"],"C","jurisprudencia",3,"É inconstitucional a exigência de depósito ou arrolamento prévios de dinheiro ou bens para a admissibilidade de recurso administrativo, entendimento que impede a lei de exigir tal depósito, apesar da ressalva \"salvo exigência legal\" do art. 56, § 2º, da Lei n.º 9.784/1999.","SV 21 do STF; Lei 9.784, art. 56, § 2º (independe de caução, salvo exigência legal).","","p16c",{"fonte":{"tipo":"sumula","ref":"STF, Súmula Vinculante 21","conferida":"conhecimento"},"risco":["jurisprudencia_mutavel"]}),
("P16",["56"],"E","jurisprudencia",3,"Segundo o STF, a lei pode condicionar a admissibilidade de recurso administrativo ao depósito prévio de dinheiro ou bens, razão pela qual a ressalva \"salvo exigência legal\" do art. 56, § 2º, da Lei n.º 9.784/1999 é plenamente aplicável.","SV 21 do STF: é inconstitucional a exigência de depósito ou arrolamento prévios para admissibilidade de recurso administrativo.","aceita depósito prévio","p16c",{"fonte":{"tipo":"sumula","ref":"STF, Súmula Vinculante 21","conferida":"conhecimento"},"risco":["jurisprudencia_mutavel"]}),
("P16",["57"],"C","troca_numero",2,"O recurso administrativo tramitará no máximo por três instâncias administrativas, salvo disposição legal diversa.","Art. 57.","","p16d",{}),
("P16",["57"],"E","troca_numero",2,"O recurso administrativo tramitará no máximo por duas instâncias administrativas, salvo disposição legal diversa.","Art. 57: três instâncias.","duas no lugar de três","p16d",{}),
("P16",["58"],"C","conceito_correto",2,"Têm legitimidade para recorrer os titulares de direitos e interesses que forem parte no processo e aqueles cujos direitos ou interesses forem indiretamente afetados pela decisão recorrida.","Art. 58, I e II.","","p16e",{}),
("P16",["58"],"E","restricao_indevida",2,"Somente quem foi parte no processo administrativo tem legitimidade para interpor recurso contra a decisão.","Art. 58, I a IV: também quem seja indiretamente afetado, organizações e associações (interesses coletivos) e cidadãos ou associações (interesses difusos).","restringe a quem foi parte","p16e",{}),
("P16",["58"],"C","caso_concreto",3,"Associação de moradores de bairro pode recorrer de decisão administrativa que afete direitos ou interesses coletivos dos moradores, ainda que não tenha sido parte no processo.","Art. 58, III.","","p16f",{}),
# P17 — Prazos recursais, efeito suspensivo e não conhecimento (arts. 59 a 63)
("P17",["59"],"C","troca_numero",1,"Salvo disposição legal específica, é de dez dias o prazo para interposição de recurso administrativo, contado da ciência ou divulgação oficial da decisão recorrida.","Art. 59, caput.","","p17a",{}),
("P17",["59"],"E","troca_numero",1,"Salvo disposição legal específica, é de trinta dias o prazo para interposição de recurso administrativo, contado da ciência ou divulgação oficial da decisão recorrida.","Art. 59, caput: dez dias.","trinta no lugar de dez","p17a",{}),
("P17",["59"],"C","troca_numero",2,"Quando a lei não fixar prazo diferente, o recurso administrativo deve ser decidido no prazo máximo de trinta dias, contado do recebimento dos autos pelo órgão competente, prorrogável por igual período mediante justificativa explícita.","Art. 59, §§ 1º e 2º.","","p17b",{}),
("P17",["59"],"E","troca_numero",2,"Quando a lei não fixar prazo diferente, o recurso administrativo deve ser decidido em dez dias, contados da sua interposição, prorrogáveis por igual período.","Art. 59, § 1º: trinta dias, a partir do recebimento dos autos pelo órgão competente.","dez dias e termo inicial na interposição","p17b",{}),
("P17",["61"],"C","conceito_correto",1,"Salvo disposição legal em contrário, o recurso administrativo não tem efeito suspensivo.","Art. 61, caput.","","p17c",{}),
("P17",["61"],"E","troca_efeito",1,"Salvo disposição legal em contrário, o recurso administrativo tem efeito suspensivo, que a autoridade só pode afastar mediante decisão motivada.","Art. 61, caput: a regra é a ausência de efeito suspensivo.","inverte a regra","p17c",{}),
("P17",["61"],"C","caso_concreto",3,"Havendo justo receio de prejuízo de difícil ou incerta reparação decorrente da execução do ato, a autoridade recorrida ou a imediatamente superior pode, de ofício ou a pedido, atribuir efeito suspensivo ao recurso.","Art. 61, parágrafo único.","","p17d",{}),
("P17",["61"],"E","caso_concreto",3,"O efeito suspensivo pode ser atribuído ao recurso administrativo, ante justo receio de prejuízo de difícil reparação, somente pela autoridade superior e unicamente a pedido do recorrente.","Art. 61, parágrafo único: a autoridade recorrida ou a imediatamente superior, de ofício ou a pedido.","restringe a autoridade e a iniciativa","p17d",{}),
("P17",["62"],"C","troca_numero",3,"Interposto o recurso, o órgão competente para dele conhecer deve intimar os demais interessados para apresentarem alegações no prazo de cinco dias úteis.","Art. 62.","","p17e",{}),
("P17",["62"],"E","troca_numero",3,"Interposto o recurso, o órgão competente para dele conhecer deve intimar os demais interessados para apresentarem alegações no prazo de dez dias corridos.","Art. 62: cinco dias úteis.","dez corridos no lugar de cinco úteis","p17e",{}),
("P17",["63"],"C","conceito_correto",2,"O recurso administrativo não será conhecido quando interposto fora do prazo, perante órgão incompetente, por quem não seja legitimado ou após exaurida a esfera administrativa.","Art. 63, I a IV.","","p17f",{}),
("P17",["63"],"C","consequencia",3,"Se o recurso for interposto perante órgão incompetente, será indicada ao recorrente a autoridade competente, sendo-lhe devolvido o prazo para recurso.","Art. 63, § 1º.","","p17g",{}),
("P17",["63"],"E","consequencia",3,"Se o recurso for interposto perante órgão incompetente, ele não será conhecido, e o recorrente perde o prazo, sem direito a nova oportunidade de recorrer.","Art. 63, § 1º: indica-se a autoridade competente e devolve-se o prazo.","nega devolução do prazo","p17g",{}),
("P17",["63"],"C","consequencia",3,"O não conhecimento do recurso não impede a Administração de rever de ofício o ato ilegal, desde que não ocorrida preclusão administrativa.","Art. 63, § 2º.","","p17h",{}),
("P17",["63"],"E","consequencia",3,"O não conhecimento do recurso impede a Administração de rever de ofício o ato ilegal, pois a decisão recorrida estabiliza-se com a perda do prazo.","Art. 63, § 2º: o não conhecimento não impede a revisão de ofício, desde que não ocorrida preclusão administrativa.","afirma impedimento da revisão de ofício","p17h",{}),
# P18 — Decisão do recurso e reformatio in pejus (art. 64)
("P18",["64"],"C","conceito_correto",2,"O órgão competente para decidir o recurso pode confirmar, modificar, anular ou revogar, total ou parcialmente, a decisão recorrida, se a matéria for de sua competência.","Art. 64, caput.","","p18a",{}),
("P18",["64"],"C","consequencia",3,"Se da decisão do recurso puder decorrer gravame à situação do recorrente, este deverá ser cientificado para formular suas alegações antes da decisão.","Art. 64, parágrafo único.","","p18b",{}),
("P18",["64"],"E","generalizacao",3,"A Lei n.º 9.784/1999 veda a reformatio in pejus no recurso administrativo, de modo que a decisão do recurso nunca pode agravar a situação do recorrente.","Art. 64, parágrafo único: a lei admite o gravame, desde que o recorrente seja cientificado para alegar antes da decisão; a vedação de agravamento está no art. 65, parágrafo único (revisão).","afirma proibição da reformatio in pejus no recurso","p18b",{}),
("P18",["64"],"C","caso_concreto",3,"Autoridade julgadora de recurso contra multa entende que o valor deveria ser maior; poderá majorá-lo, desde que antes cientifique o recorrente para que apresente suas alegações.","Art. 64, caput e parágrafo único.","","p18c",{}),
("P18",["64"],"E","caso_concreto",3,"Autoridade julgadora de recurso contra multa pode majorá-la de imediato, sem ouvir o recorrente, por ser matéria de sua competência.","Art. 64, parágrafo único: ciência ao recorrente para alegações antes da decisão que possa gravar sua situação.","dispensa ciência prévia","p18c",{}),
# P19 — Revisão (art. 65)
("P19",["65"],"C","conceito_correto",2,"Os processos administrativos de que resultem sanções podem ser revistos, a qualquer tempo, a pedido ou de ofício, quando surgirem fatos novos ou circunstâncias relevantes suscetíveis de justificar a inadequação da sanção aplicada.","Art. 65, caput.","","p19a",{}),
("P19",["65"],"E","troca_numero",2,"A revisão do processo administrativo de que resultem sanções só pode ser requerida no prazo de cinco anos, contados da aplicação da sanção, por quem tenha sido sancionado.","Art. 65, caput: a qualquer tempo, a pedido ou de ofício.","impõe prazo e restringe legitimidade","p19a",{}),
("P19",["65"],"C","consequencia",2,"Da revisão do processo administrativo de que resultou sanção não poderá resultar agravamento da sanção.","Art. 65, parágrafo único.","","p19b",{}),
("P19",["65"],"E","consequencia",3,"Na revisão de ofício de processo sancionador, a autoridade pode agravar a sanção, desde que cientifique o interessado para alegações, aplicando-se a regra do recurso.","Art. 65, parágrafo único: da revisão não poderá resultar agravamento da sanção. A ressalva com ciência prévia é do art. 64 (recurso).","aplica à revisão a regra do recurso","p19b",{}),
("P19",["64","65"],"C","confusao_instituto",3,"Enquanto, no recurso, a Lei n.º 9.784/1999 admite que da decisão resulte gravame ao recorrente, desde que ele seja cientificado para alegar, na revisão do processo sancionador o agravamento da sanção é vedado.","Art. 64, parágrafo único, e art. 65, parágrafo único.","","p19c",{}),
# P20 — Contagem de prazos (arts. 66 e 67)
("P20",["66"],"C","conceito_correto",2,"Os prazos começam a correr a partir da data da cientificação oficial, excluindo-se da contagem o dia do começo e incluindo-se o do vencimento.","Art. 66, caput.","","p20a",{}),
("P20",["66"],"E","troca_efeito",2,"Os prazos começam a correr da cientificação oficial, incluindo-se na contagem o dia do começo e excluindo-se o do vencimento.","Art. 66, caput: exclui-se o dia do começo e inclui-se o do vencimento.","inverte a regra de contagem","p20a",{}),
("P20",["66"],"C","conceito_correto",2,"Considera-se prorrogado o prazo até o primeiro dia útil seguinte se o vencimento cair em dia sem expediente ou em que o expediente for encerrado antes da hora normal.","Art. 66, § 1º.","","p20b",{}),
("P20",["66"],"C","conceito_correto",3,"Os prazos expressos em dias contam-se de modo contínuo, e os fixados em meses ou anos contam-se de data a data, adotando-se como termo o último dia do mês se não houver o dia equivalente.","Art. 66, §§ 2º e 3º.","","p20c",{}),
("P20",["66"],"E","troca_efeito",3,"Os prazos expressos em dias contam-se apenas em dias úteis, suspendendo-se nos sábados, domingos e feriados.","Art. 66, § 2º: os prazos em dias contam-se de modo contínuo; a lei refere dias úteis apenas onde o diz expressamente (arts. 26, § 2º, 41 e 62).","aplica contagem em dias úteis à regra geral","p20c",{}),
("P20",["67"],"C","conceito_correto",2,"Salvo motivo de força maior devidamente comprovado, os prazos processuais não se suspendem.","Art. 67.","","p20d",{}),
("P20",["67"],"E","excecao_omitida",2,"Os prazos processuais suspendem-se sempre que houver pedido fundamentado do interessado, a juízo da autoridade responsável pelo processo.","Art. 67: não se suspendem, salvo motivo de força maior devidamente comprovado.","admite suspensão por pedido","p20d",{}),
("P20",["66"],"C","caso_concreto",3,"Interessado cientificado oficialmente de decisão em 3 de março, dia útil, tem dez dias para recorrer; o prazo vence em 13 de março, e recurso protocolado em 14 de março, dia útil, é intempestivo.","Art. 59, caput, e art. 66, caput: exclui-se o dia 3 e inclui-se o dia do vencimento (13); o dia 14 já está fora do prazo.","","p20e",{}),
("P20",["66"],"E","caso_concreto",3,"Interessado cientificado oficialmente de decisão em 3 de março, dia útil, tem dez dias para recorrer; recurso protocolado em 13 de março, dia útil, é intempestivo.","Art. 59, caput, e art. 66, caput: exclui-se o dia 3 e inclui-se o dia do vencimento; 13 de março é o último dia do prazo, logo o recurso é tempestivo.","erra a contagem (inclui o dia do começo)","p20e",{}),
# P21 — Sanções e aplicação subsidiária (arts. 68 e 69)
("P21",["68"],"C","conceito_correto",2,"As sanções previstas na Lei n.º 9.784/1999 têm natureza pecuniária ou consistem em obrigação de fazer ou de não fazer, assegurado sempre o direito de defesa.","Art. 68.","","p21a",{}),
("P21",["68"],"E","troca_efeito",2,"As sanções previstas na Lei n.º 9.784/1999 podem consistir em suspensão de direitos ou perda de função pública, assegurada a defesa antes da aplicação.","Art. 68: natureza pecuniária ou obrigação de fazer ou não fazer.","inclui sanções não previstas","p21a",{}),
("P21",["69"],"C","conceito_correto",2,"Os processos administrativos específicos continuam a reger-se por lei própria, aplicando-se-lhes apenas subsidiariamente a Lei n.º 9.784/1999.","Art. 69.","","p21b",{}),
("P21",["69"],"E","troca_efeito",2,"Os processos administrativos específicos regem-se pela Lei n.º 9.784/1999, que prevalece sobre as leis próprias em caso de conflito, as quais se aplicam apenas supletivamente.","Art. 69: a lei própria rege o processo específico; a Lei 9.784 é subsidiária.","inverte a relação de subsidiariedade","p21b",{}),
("P21",["69"],"C","caso_concreto",3,"Sobre a prescrição e as garantias do processo disciplinar de servidor federal prevalecem as regras da lei própria (Lei n.º 8.112/1990), aplicando-se a Lei n.º 9.784/1999 apenas nos pontos em que aquela for omissa.","Art. 69 da Lei 9.784.","","p21c",{"fonte":{"tipo":"lei","ref":"Lei 9.784/99, art. 69 (aplicação à Lei 8.112/90 por conhecimento)","conferida":"conhecimento"}}),
# P22 — Jurisprudência correlata
("P22",["53"],"C","jurisprudencia",2,"Segundo a Súmula 473 do STF, a Administração pode anular seus próprios atos quando eivados de vícios que os tornam ilegais, ou revogá-los por conveniência ou oportunidade, respeitados os direitos adquiridos e ressalvada a apreciação judicial.","STF, Súmula 473; reflete o art. 53 da Lei 9.784/99.","","p22a",{"fonte":{"tipo":"sumula","ref":"STF, Súmula 473","conferida":"conhecimento"},"risco":["jurisprudencia_mutavel"]}),
("P22",["53"],"E","jurisprudencia",2,"Segundo a Súmula 473 do STF, a Administração depende de prévia autorização judicial para anular seus atos ilegais ou para revogá-los por conveniência ou oportunidade.","STF, Súmulas 346 e 473: a Administração anula e revoga seus atos por autotutela, sem autorização judicial, ressalvada a apreciação judicial posterior.","exige autorização judicial","p22a",{"fonte":{"tipo":"sumula","ref":"STF, Súmula 473","conferida":"conhecimento"},"risco":["jurisprudencia_mutavel"]}),
("P22",["53"],"C","jurisprudencia",2,"A Administração Pública pode declarar a nulidade dos seus próprios atos, conforme a Súmula 346 do STF.","STF, Súmula 346.","","p22b",{"fonte":{"tipo":"sumula","ref":"STF, Súmula 346","conferida":"conhecimento"},"risco":["jurisprudencia_mutavel"]}),
("P22",["54"],"C","jurisprudencia",3,"O STJ entende que a Lei n.º 9.784/1999, especialmente o seu art. 54, aplica-se subsidiariamente aos processos administrativos estaduais e municipais, se inexistir norma local e específica que regule a matéria.","STJ, Súmula 633.","","p22c",{"fonte":{"tipo":"sumula","ref":"STJ, Súmula 633","conferida":"conhecimento"},"risco":["jurisprudencia_mutavel"]}),
("P22",["54"],"E","jurisprudencia",3,"O STJ entende que a Lei n.º 9.784/1999 é de aplicação obrigatória aos Estados e Municípios, prevalecendo sobre as normas locais que disciplinem o processo administrativo.","STJ, Súmula 633: aplicação subsidiária aos entes estaduais e municipais, se inexistir norma local e específica.","afirma aplicação obrigatória e prevalente","p22c",{"fonte":{"tipo":"sumula","ref":"STJ, Súmula 633","conferida":"conhecimento"},"risco":["jurisprudencia_mutavel"]}),
("P22",["3"],"C","jurisprudencia",3,"A falta de defesa técnica por advogado no processo administrativo disciplinar não ofende a Constituição, segundo a Súmula Vinculante 5 do STF.","STF, SV 5; compatível com o art. 3º, IV, da Lei 9.784 (assistência facultativa).","","p22d",{"fonte":{"tipo":"sumula","ref":"STF, Súmula Vinculante 5","conferida":"conhecimento"},"risco":["jurisprudencia_mutavel"]}),
("P22",["3"],"E","jurisprudencia",3,"A ausência de defesa técnica por advogado em processo administrativo disciplinar viola a ampla defesa, segundo a Súmula Vinculante 5 do STF.","STF, SV 5: a falta de defesa técnica por advogado no PAD não ofende a Constituição.","inverte o entendimento","p22d",{"fonte":{"tipo":"sumula","ref":"STF, Súmula Vinculante 5","conferida":"conhecimento"},"risco":["jurisprudencia_mutavel"]}),
("P22",["64"],"C","jurisprudencia",3,"Nos processos perante o TCU, asseguram-se o contraditório e a ampla defesa quando da decisão puder resultar anulação ou revogação de ato que beneficie o interessado, excetuada a apreciação da legalidade do ato de concessão inicial de aposentadoria, reforma e pensão.","STF, Súmula Vinculante 3.","","p22e",{"fonte":{"tipo":"sumula","ref":"STF, Súmula Vinculante 3","conferida":"conhecimento"},"risco":["jurisprudencia_mutavel"]}),
("P22",["64"],"E","jurisprudencia",3,"Nos processos perante o TCU, o contraditório e a ampla defesa são assegurados também na apreciação da legalidade do ato de concessão inicial de aposentadoria, reforma e pensão, segundo a Súmula Vinculante 3 do STF.","STF, SV 3: o contraditório e a ampla defesa não se aplicam à apreciação da legalidade do ato de concessão inicial de aposentadoria, reforma e pensão.","retira a exceção","p22e",{"fonte":{"tipo":"sumula","ref":"STF, Súmula Vinculante 3","conferida":"conhecimento"},"risco":["jurisprudencia_mutavel"]}),
# P23 — Casos concretos integrados
("P23",["50"],"C","caso_concreto",2,"Indeferido requerimento de licença de servidor sem indicação dos fatos e dos fundamentos jurídicos da decisão, o ato é viciado por falta de motivação, pois nega ou afeta direito do interessado.","Art. 50, I e caput.","","p23a",{}),
("P23",["26"],"C","caso_concreto",3,"Interessado intimado por telegrama a comparecer com antecedência de dois dias úteis comparece à data marcada; a irregularidade da intimação foi suprida pelo comparecimento.","Art. 26, §§ 2º e 5º.","","p23b",{}),
("P23",["26"],"E","caso_concreto",3,"Interessado intimado por telegrama a comparecer com antecedência de dois dias úteis comparece à data marcada; a intimação continua nula, porque o comparecimento não convalida o descumprimento da antecedência mínima legal.","Art. 26, § 5º: o comparecimento supre a falta ou irregularidade.","nega o suprimento pelo comparecimento","p23b",{}),
("P23",["49"],"C","caso_concreto",2,"A Administração que decide pedido quarenta e cinco dias após a conclusão da instrução, sem ter prorrogado o prazo por decisão expressamente motivada, descumpre o prazo do art. 49 da Lei n.º 9.784/1999.","Art. 49: trinta dias, prorrogáveis por igual período mediante motivação expressa.","","p23c",{}),
("P23",["49"],"E","caso_concreto",2,"A Administração que decide pedido quarenta e cinco dias após a conclusão da instrução, sem ter prorrogado o prazo, cumpre o art. 49 da Lei n.º 9.784/1999, que fixa o prazo de sessenta dias.","Art. 49: trinta dias, prorrogáveis por igual período mediante motivação expressa.","sessenta no lugar de trinta","p23c",{}),
("P23",["12","13"],"E","caso_concreto",3,"O titular de órgão colegiado pode delegar a seu presidente a decisão de recursos administrativos, por aplicação analógica da regra de delegação dos colegiados aos respectivos presidentes.","Art. 12, parágrafo único, permite a delegação dos colegiados aos presidentes, mas o art. 13, II, veda a delegação da decisão de recursos administrativos.","aplica art. 12 sem observar a vedação do art. 13, II","p23d",{}),
("P23",["19","20"],"C","caso_concreto",3,"Servidor que tem amizade íntima com o interessado não está impedido, mas pode ter sua suspeição arguida; servidor que litiga judicialmente com o interessado está impedido e deve comunicar o fato.","Arts. 18, III, 19 e 20.","","p23e",{}),
]
